<?php
declare(strict_types=1);
require_once __DIR__.'/payments.php';
require_once __DIR__.'/marketplace_v550.php';

function store_slug(string $title,int $ignore=0): string {
    $base=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$title),'-'))?:'product';$slug=$base;$i=2;
    while(true){$sql='SELECT id FROM store_products WHERE slug=?'.($ignore?' AND id<>'.(int)$ignore:'').' LIMIT 1';$q=db()->prepare($sql);$q->execute([$slug]);if(!$q->fetchColumn())return $slug;$slug=$base.'-'.$i++;}
}
function store_category_slug(string $title,int $ignore=0): string {
    $base=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$title),'-'))?:'category';$slug=$base;$i=2;
    while(true){$sql='SELECT id FROM store_categories WHERE slug=?'.($ignore?' AND id<>'.(int)$ignore:'').' LIMIT 1';$q=db()->prepare($sql);$q->execute([$slug]);if(!$q->fetchColumn())return $slug;$slug=$base.'-'.$i++;}
}
function store_categories(): array {try{return db()->query('SELECT * FROM store_categories WHERE status=1 ORDER BY sort_order,name')->fetchAll();}catch(Throwable $e){return [];}}
function store_product($idOrSlug): ?array {
    $field=is_int($idOrSlug)||ctype_digit((string)$idOrSlug)?'p.id':'p.slug';$where=["{$field}=?"];$params=[$idOrSlug];if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$params,'p.city_id');
    $q=db()->prepare("SELECT p.*,sc.name category_name,sc.slug category_slug,c.name city_name,b.name business_name,u.name seller_name FROM store_products p JOIN store_categories sc ON sc.id=p.category_id LEFT JOIN cities c ON c.id=p.city_id LEFT JOIN businesses b ON b.id=p.business_id JOIN users u ON u.id=p.seller_user_id WHERE ".implode(' AND ',$where)." LIMIT 1");$q->execute($params);return $q->fetch()?:null;
}
function store_products(array $filters=[],int $limit=24): array {
    store_auction_sync();$where=["p.status='published'"];$params=[];
    if(!empty($filters['seller'])){$where[]='p.seller_user_id=?';$params[]=(int)$filters['seller'];}
    if(!empty($filters['product_type'])){$where[]='p.product_type=?';$params[]=$filters['product_type'];}
    if(!empty($filters['sale_mode'])){$where[]='p.sale_mode=?';$params[]=$filters['sale_mode'];}
    if(!empty($filters['category'])){$where[]='sc.slug=?';$params[]=$filters['category'];}
    if(!empty($filters['city'])){$where[]='c.slug=?';$params[]=$filters['city'];}
    elseif(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$params,'p.city_id');
    if(!empty($filters['featured']))$where[]='p.featured=1';
    if(!empty($filters['q'])){$where[]='(p.title LIKE ? OR p.short_description LIKE ? OR p.description LIKE ?)';$like='%'.$filters['q'].'%';array_push($params,$like,$like,$like);}
    $boostOrder=(function_exists('v41_table_exists')&&v41_table_exists('listing_boosts'))?"(SELECT COUNT(*) FROM listing_boosts lb WHERE lb.entity_type='product' AND lb.entity_id=p.id AND lb.status='active' AND lb.starts_at<=NOW() AND lb.ends_at>=NOW()) DESC,":'';$order=($filters['sort']??'')==='price_asc'?'p.price ASC':(($filters['sort']??'')==='price_desc'?'p.price DESC':$boostOrder.'p.featured DESC,p.id DESC');
    $sql="SELECT p.*,sc.name category_name,sc.slug category_slug,c.name city_name,b.name business_name,u.name seller_name,a.id auction_id,a.current_price,a.min_increment,a.starts_at auction_starts,a.ends_at auction_ends,a.status auction_status FROM store_products p JOIN store_categories sc ON sc.id=p.category_id LEFT JOIN cities c ON c.id=p.city_id LEFT JOIN businesses b ON b.id=p.business_id JOIN users u ON u.id=p.seller_user_id LEFT JOIN store_auctions a ON a.product_id=p.id WHERE ".implode(' AND ',$where)." ORDER BY {$order} LIMIT ".max(1,min(100,$limit));
    try{$q=db()->prepare($sql);$q->execute($params);return $q->fetchAll();}catch(Throwable $e){return [];}
}
function store_stats(): array {store_auction_sync();try{$city=function_exists('tenant_query_city_id')?tenant_query_city_id():0;if($city>0){$q=db()->prepare("SELECT (SELECT COUNT(*) FROM store_products WHERE city_id=?) products,(SELECT COUNT(*) FROM store_products WHERE city_id=? AND status='published') published,(SELECT COUNT(*) FROM store_products WHERE city_id=? AND product_type='used' AND status='published') used_count,(SELECT COUNT(*) FROM store_products WHERE city_id=? AND product_type='digital' AND status='published') digital_count,(SELECT COUNT(*) FROM store_auctions a JOIN store_products p ON p.id=a.product_id WHERE p.city_id=? AND a.status='live') live_auctions,(SELECT COUNT(*) FROM store_orders o JOIN store_products p ON p.seller_user_id=o.seller_user_id WHERE p.city_id=?) orders,(SELECT COALESCE(SUM(o.grand_total),0) FROM store_orders o WHERE o.status NOT IN ('cancelled') AND EXISTS(SELECT 1 FROM store_products p WHERE p.seller_user_id=o.seller_user_id AND p.city_id=?)) gross_value");$q->execute([$city,$city,$city,$city,$city,$city,$city]);return $q->fetch()?:[];}return db()->query("SELECT (SELECT COUNT(*) FROM store_products) products,(SELECT COUNT(*) FROM store_products WHERE status='published') published,(SELECT COUNT(*) FROM store_products WHERE product_type='used' AND status='published') used_count,(SELECT COUNT(*) FROM store_products WHERE product_type='digital' AND status='published') digital_count,(SELECT COUNT(*) FROM store_auctions WHERE status='live') live_auctions,(SELECT COUNT(*) FROM store_orders) orders,(SELECT COALESCE(SUM(grand_total),0) FROM store_orders WHERE status NOT IN ('cancelled')) gross_value")->fetch()?:[];}catch(Throwable $e){return [];}}
function store_seller_stats(int $uid): array {try{$q=db()->prepare("SELECT (SELECT COUNT(*) FROM store_products WHERE seller_user_id=?) products,(SELECT COUNT(*) FROM store_products WHERE seller_user_id=? AND status='published') published,(SELECT COUNT(*) FROM store_orders WHERE seller_user_id=?) orders,(SELECT COUNT(*) FROM store_orders WHERE seller_user_id=? AND status IN ('pending','confirmed','processing')) open_orders,(SELECT COALESCE(SUM(grand_total),0) FROM store_orders WHERE seller_user_id=? AND status NOT IN ('cancelled')) gross");$q->execute([$uid,$uid,$uid,$uid,$uid]);return $q->fetch()?:[];}catch(Throwable $e){return [];}}
function store_owned_businesses(int $uid): array {try{$where=['owner_id=?','status=1'];$params=[$uid];if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$params,'city_id');$q=db()->prepare('SELECT id,name FROM businesses WHERE '.implode(' AND ',$where).' ORDER BY name');$q->execute($params);return $q->fetchAll();}catch(Throwable $e){return [];}}
function store_cart(): array {return is_array($_SESSION['store_cart']??null)?$_SESSION['store_cart']:[];}
function store_cart_clear(): void {unset($_SESSION['store_cart']);}
function store_cart_add(int $productId,int $qty=1): void {
    $p=store_product($productId);if(!$p||$p['status']!=='published'||$p['sale_mode']!=='fixed')throw new RuntimeException('Product is not available for direct purchase.');
    if((int)$p['stock']<1)throw new RuntimeException('Product is out of stock.');$cart=store_cart();
    foreach($cart as $id=>$row){$existing=store_product((int)$id);if($existing&&(int)$existing['seller_user_id']!==(int)$p['seller_user_id'])throw new RuntimeException('For local fulfilment, one order can contain products from only one seller. Checkout the current cart first.');}
    $qty=max(1,min((int)$p['stock'],$qty));$current=(int)($cart[$productId]['qty']??0);$cart[$productId]=['qty'=>min((int)$p['stock'],$current+$qty)];$_SESSION['store_cart']=$cart;
}
function store_cart_remove(int $productId): void {$cart=store_cart();unset($cart[$productId]);$_SESSION['store_cart']=$cart;}
function store_cart_details(): array {
    $items=[];$subtotal=0;$shipping=0;$seller=null;$hasDigital=false;$allowCod=true;$allowAdvance=true;
    foreach(store_cart() as $id=>$row){$p=store_product((int)$id);if(!$p||$p['status']!=='published'||$p['sale_mode']!=='fixed')continue;$qty=max(1,min((int)$p['stock'],(int)$row['qty']));$line=(float)$p['price']*$qty;$ship=(float)$p['shipping_charge'];$subtotal+=$line;$shipping+=$ship;$seller=(int)$p['seller_user_id'];$hasDigital=$hasDigital||$p['product_type']==='digital';$allowCod=$allowCod&&((int)$p['allow_cod']===1)&&$p['product_type']!=='digital';$allowAdvance=$allowAdvance&&((int)$p['allow_advance']===1);$items[]=['product'=>$p,'qty'=>$qty,'line_total'=>$line];}
    return ['items'=>$items,'subtotal'=>$subtotal,'shipping'=>$shipping,'grand_total'=>$subtotal+$shipping,'seller_user_id'=>$seller,'has_digital'=>$hasDigital,'allow_cod'=>$allowCod,'allow_advance'=>$allowAdvance];
}
function store_order_number(): string {return 'SHP-ORD-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(4)));}
function store_create_order(int $buyer,string $method,array $customer,?int $auctionId=null): int {
    if(!in_array($method,['cod','advance'],true))throw new RuntimeException('Invalid payment method.');$cart=store_cart_details();
    if($auctionId){$aw=['a.id=?'];$ap=[$auctionId];if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($aw,$ap,'p.city_id');$q=db()->prepare("SELECT a.*,p.* FROM store_auctions a JOIN store_products p ON p.id=a.product_id WHERE ".implode(' AND ',$aw)." LIMIT 1");$q->execute($ap);$a=$q->fetch();if(!$a||$a['status']!=='ended'||(int)$a['winner_user_id']!==$buyer)throw new RuntimeException('This auction is not available for winner checkout.');$q=db()->prepare('SELECT id FROM store_orders WHERE auction_id=? LIMIT 1');$q->execute([$auctionId]);if($q->fetchColumn())throw new RuntimeException('Winning auction order already exists.');$cart=['items'=>[['product'=>$a,'qty'=>1,'line_total'=>(float)$a['current_price']]],'subtotal'=>(float)$a['current_price'],'shipping'=>(float)$a['shipping_charge'],'grand_total'=>(float)$a['current_price']+(float)$a['shipping_charge'],'seller_user_id'=>(int)$a['seller_user_id'],'has_digital'=>$a['product_type']==='digital','allow_cod'=>(int)$a['allow_cod']===1&&$a['product_type']!=='digital','allow_advance'=>(int)$a['allow_advance']===1];}
    if(!$cart['items'])throw new RuntimeException('Cart is empty.');if($cart['has_digital']&&$method==='cod')throw new RuntimeException('Digital products require advance payment.');
    if($method==='cod'&&(!setting_bool('store_cod_enabled',true)||empty($cart['allow_cod'])))throw new RuntimeException('Cash on delivery is not available for one or more products in this order.');
    if($method==='advance'&&(!setting_bool('store_advance_enabled',true)||empty($cart['allow_advance'])))throw new RuntimeException('Advance payment is not available for one or more products in this order.');
    db()->beginTransaction();try{
        foreach($cart['items'] as $row){$pid=(int)$row['product']['id'];$qty=(int)$row['qty'];$lock=db()->prepare('SELECT stock,status FROM store_products WHERE id=? FOR UPDATE');$lock->execute([$pid]);$stock=$lock->fetch();if(!$stock||$stock['status']!=='published'||(int)$stock['stock']<$qty)throw new RuntimeException('A product is no longer available in the requested quantity.');}
        $q=db()->prepare("INSERT INTO store_orders(order_number,buyer_user_id,seller_user_id,auction_id,subtotal,shipping_total,grand_total,payment_method,payment_status,status,customer_name,customer_phone,customer_email,shipping_address,city_text,notes) VALUES(?,?,?,?,?,?,?,?,'unpaid','pending',?,?,?,?,?,?)");
        $q->execute([store_order_number(),$buyer,$cart['seller_user_id'],$auctionId,$cart['subtotal'],$cart['shipping'],$cart['grand_total'],$method,trim($customer['name']),trim($customer['phone']),trim($customer['email']??'')?:null,trim($customer['address']??'')?:null,trim($customer['city']??'')?:null,trim($customer['notes']??'')?:null]);$orderId=(int)db()->lastInsertId();
        $iq=db()->prepare('INSERT INTO store_order_items(order_id,product_id,title,product_type,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?,?)');
        foreach($cart['items'] as $row){$p=$row['product'];$iq->execute([$orderId,$p['id'],$p['title'],$p['product_type'],$row['qty'],$row['line_total']/$row['qty'],$row['line_total']]);db()->prepare("UPDATE store_products SET stock=stock-?,status=IF(stock-?<=0,'soldout',status) WHERE id=?")->execute([$row['qty'],$row['qty'],$p['id']]);}
        if($method==='advance'){$paymentId=create_payment_order($buyer,(float)$cart['grand_total'],'ecommerce',null,null,null,'none',['store_order_id'=>$orderId]);db()->prepare("UPDATE store_orders SET payment_order_id=?,payment_status='unpaid' WHERE id=?")->execute([$paymentId,$orderId]);}
        db()->commit();if(function_exists('operations_ensure_invoice')){try{operations_ensure_invoice($orderId);foreach($cart['items'] as $row){$pp=$row['product'];if(function_exists('inventory_log_only'))inventory_log_only((int)$pp['seller_user_id'],(int)$pp['id'],-(int)$row['qty'],'sale','order',$orderId,'Stock sold via marketplace',$buyer);}}catch(Throwable $e){runtime_log('Post-order operations skipped',$e);}}if(!$auctionId)store_cart_clear();return $orderId;
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function store_order(int $id): ?array {$q=db()->prepare("SELECT o.*,bu.name buyer_name,su.name seller_name,po.reference payment_reference,po.status payment_order_status FROM store_orders o JOIN users bu ON bu.id=o.buyer_user_id JOIN users su ON su.id=o.seller_user_id LEFT JOIN payment_orders po ON po.id=o.payment_order_id WHERE o.id=? LIMIT 1");$q->execute([$id]);return $q->fetch()?:null;}
function store_order_items(int $id): array {$q=db()->prepare('SELECT oi.*,p.slug,p.digital_file_path,p.image_url FROM store_order_items oi JOIN store_products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');$q->execute([$id]);return $q->fetchAll();}
function store_cancel_order(int $id): void {
    $q=db()->prepare('SELECT * FROM store_orders WHERE id=? FOR UPDATE');db()->beginTransaction();try{$q->execute([$id]);$o=$q->fetch();if(!$o)throw new RuntimeException('Order not found.');if($o['status']==='cancelled'){db()->commit();return;}if(in_array($o['status'],['delivered','completed'],true))throw new RuntimeException('Delivered/completed order cannot be cancelled.');if($o['payment_status']==='paid')throw new RuntimeException('Paid order cannot be cancelled until its payment is refunded/reversed by an administrator.');$items=store_order_items($id);foreach($items as $it)db()->prepare("UPDATE store_products SET stock=stock+?,status=IF(status='soldout','published',status) WHERE id=?")->execute([$it['quantity'],$it['product_id']]);db()->prepare("UPDATE store_orders SET status='cancelled' WHERE id=?")->execute([$id]);db()->commit();if(function_exists('inventory_log_only'))foreach($items as $it)inventory_log_only((int)$o['seller_user_id'],(int)$it['product_id'],(int)$it['quantity'],'return_in','order',$id,'Cancelled order stock restored',null);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function store_auction_sync(): void {
    try{db()->exec("UPDATE store_auctions SET status='live' WHERE status='scheduled' AND starts_at<=NOW() AND ends_at>NOW()");
        $rows=db()->query("SELECT id FROM store_auctions WHERE status IN ('scheduled','live') AND ends_at<=NOW()")->fetchAll();foreach($rows as $r){$q=db()->prepare('SELECT user_id,bid_amount FROM store_auction_bids WHERE auction_id=? ORDER BY bid_amount DESC,id ASC LIMIT 1');$q->execute([$r['id']]);$winner=$q->fetch();db()->prepare("UPDATE store_auctions SET status='ended',winner_user_id=?,current_price=IFNULL(?,current_price) WHERE id=?")->execute([$winner['user_id']??null,$winner['bid_amount']??null,$r['id']]);}
    }catch(Throwable $e){}
}
function store_auction(int $id): ?array {store_auction_sync();$where=['a.id=?'];$params=[$id];if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$params,'p.city_id');$q=db()->prepare("SELECT a.*,p.title,p.slug,p.image_url,p.description,p.short_description,p.seller_user_id,p.shipping_charge,p.product_type,p.business_id,p.city_id,p.allow_cod,p.allow_advance,u.name seller_name FROM store_auctions a JOIN store_products p ON p.id=a.product_id JOIN users u ON u.id=p.seller_user_id WHERE ".implode(' AND ',$where)." LIMIT 1");$q->execute($params);return $q->fetch()?:null;}
function store_place_bid(int $auctionId,int $uid,float $amount): void {
    if(!setting_bool('store_auction_enabled',true))throw new RuntimeException('Auctions are disabled.');db()->beginTransaction();try{$q=db()->prepare("SELECT a.*,p.seller_user_id FROM store_auctions a JOIN store_products p ON p.id=a.product_id WHERE a.id=? FOR UPDATE");$q->execute([$auctionId]);$a=$q->fetch();if(!$a)throw new RuntimeException('Auction not found.');$now=time();if($a['status']!=='live'||strtotime($a['starts_at'])>$now||strtotime($a['ends_at'])<=$now)throw new RuntimeException('Auction is not live.');if((int)$a['seller_user_id']===$uid)throw new RuntimeException('Seller cannot bid on own product.');$minimum=(float)$a['current_price']+(float)$a['min_increment'];if($amount<$minimum)throw new RuntimeException('Minimum next bid is Rs '.number_format($minimum,2).'.');db()->prepare('INSERT INTO store_auction_bids(auction_id,user_id,bid_amount) VALUES(?,?,?)')->execute([$auctionId,$uid,$amount]);db()->prepare('UPDATE store_auctions SET current_price=? WHERE id=?')->execute([$amount,$auctionId]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function store_bids(int $auctionId,int $limit=20): array {$q=db()->prepare('SELECT b.*,u.name FROM store_auction_bids b JOIN users u ON u.id=b.user_id WHERE b.auction_id=? ORDER BY b.bid_amount DESC,b.id DESC LIMIT '.max(1,min(100,$limit)));$q->execute([$auctionId]);return $q->fetchAll();}
function store_upload_image(array $file): ?string {if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;if(($file['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new RuntimeException('Image upload failed.');if(($file['size']??0)>8*1024*1024)throw new RuntimeException('Image must be 8MB or smaller.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new RuntimeException('Use JPG, PNG or WEBP.');$dir=__DIR__.'/../uploads/store';if(!is_dir($dir))mkdir($dir,0755,true);$name=date('YmdHis').'-'.bin2hex(random_bytes(6)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Unable to save image.');return '/uploads/store/'.$name;}
function store_upload_digital(array $file): ?string {if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;if(($file['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new RuntimeException('Digital file upload failed.');if(($file['size']??0)>100*1024*1024)throw new RuntimeException('Digital file must be 100MB or smaller.');$name=(string)($file['name']??'file');$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$allowed=['zip','pdf','png','jpg','jpeg','webp','mp3','mp4','txt','csv','xlsx','docx'];if(!in_array($ext,$allowed,true))throw new RuntimeException('This digital file type is not allowed.');$dir=__DIR__.'/../storage/digital_products';if(!is_dir($dir))mkdir($dir,0750,true);$safe=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$safe))throw new RuntimeException('Unable to save digital product.');return 'storage/digital_products/'.$safe;}
function store_upgrade_homepage(): void {
    if(!setting_bool('store_home_enabled',true))return;try{if(setting_int('store_homepage_version',0)>=340)return;$page=cms_home_page();if(!$page)return;$sections=cms_page_sections($page);$found=false;foreach($sections as $s)if(($s['type']??'')==='shop_widget'){$found=true;break;}if(!$found){$sections[]=['id'=>'marketplace_widget','type'=>'shop_widget','enabled'=>1,'order'=>78,'title'=>'Shahkot Marketplace','subtitle'=>'New · Used · Digital · Auctions','content'=>'Shop locally from verified sellers and businesses.','image'=>'','items'=>''];usort($sections,fn($a,$b)=>(int)($a['order']??0)<=>(int)($b['order']??0));$o=10;foreach($sections as &$s){$s['order']=$o;$o+=10;}unset($s);$json=cms_encode_layout($sections);db()->prepare('UPDATE cms_pages SET layout_json=?,updated_at=NOW() WHERE id=?')->execute([$json,$page['id']]);save_setting('homepage_sections',$json);}save_setting('store_homepage_version','340');}catch(Throwable $e){}
}
function store_render_widget(): void {
    if(function_exists('mp550_enabled')&&mp550_enabled()){mp550_render_home_widget();return;}
    if(!setting_bool('store_enabled',true)||!setting_bool('store_home_enabled',true))return;$rows=store_products([],max(1,min(12,setting_int('store_items_limit',8))));
    echo '<section class="lc-shop-widget"><div class="lt-shell"><div class="lc-section-head"><div><span>MARKETPLACE</span><h2>Shop local. Buy new, used & digital.</h2><p>Products, auctions and local seller listings in one city marketplace.</p></div><a href="/shop.php">Open Shop →</a></div><div class="lc-shop-grid">';
    if(!$rows)echo '<div class="lc-empty">Marketplace products will appear here as sellers publish listings.</div>';
    foreach($rows as $p){$price=$p['sale_mode']==='auction'?(float)($p['current_price']?:$p['price']):(float)$p['price'];echo '<a class="lc-product-card" href="/product.php?slug='.urlencode($p['slug']).'"><div class="lc-product-image"'.($p['image_url']?' style="background-image:url(\''.e($p['image_url']).'\')"':'').'><span>'.e(strtoupper($p['product_type'])).'</span>'.($p['sale_mode']==='auction'?'<em>AUCTION</em>':'').'</div><div><small>'.e($p['category_name']).' · '.e($p['city_name']?:setting('default_city','Shahkot')).'</small><h3>'.e($p['title']).'</h3><p>'.e($p['seller_name']).'</p><b>Rs '.e(number_format($price,0)).'</b></div></a>';}
    echo '</div></div></section>';
}
